@@ -143,17 +143,21 @@
     ctx.fillStyle = 'orange';
     ctx.fill();
   }
 ctx.restore();
-  // Asteroids with gradient shading
+  // Asteroids with gradient shading and rotation
   for (let a of asteroids) {
-    const gradA = ctx.createRadialGradient(a.x, a.y, a.r * 0.2, a.x, a.y, a.r);
+    ctx.save();
+    ctx.translate(a.x, a.y);
+    ctx.rotate(a.angle);
+    const gradA = ctx.createRadialGradient(0, 0, a.r * 0.2, 0, 0, a.r);
     gradA.addColorStop(0, '#888888');
     gradA.addColorStop(1, '#222222');
     ctx.fillStyle = gradA;
     ctx.beginPath();
-    ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
+    ctx.arc(0, 0, a.r, 0, Math.PI * 2);
     ctx.fill();
+    ctx.restore();
   }
 // UI
 ctx.fillStyle = 'lime';
 ctx.font = '16px monospace';

