input.oldString:
for (let a of asteroids) {
  a.x += a.vx;
  a.y += a.vy;
  // wrap
  if (a.x < -30) a.x += canvas.width + 60;
  if (a.x > canvas.width + 30) a.x -= canvas.width + 60;
  if (a.y < -30) a.y += canvas.height + 60;
  if (a.y > canvas.height + 30) a.y -= canvas.height + 60;
}

input.newString:
for (let a of asteroids) {
  a.x += a.vx;
  a.y += a.vy;
  a.angle += a.rotSpeed;
  // wrap
  if (a.x < -30) a.x += canvas.width + 60;
  if (a.x > canvas.width + 30) a.x -= canvas.width + 60;
  if (a.y < -30) a.y += canvas.height + 60;
  if (a.y > canvas.height + 30) a.y -= canvas.height + 60;
}

